//! Frozen SemanticDB and syntax rows were generated by the actual pinned Scala
//! compiler. The independent JVM witness verifies callback creation is deferred.
use selector_extract::{ExtractOptions, import_capture};
use selector_facts::{FactSnapshot, OperationRecord};
use selector_types::*;
use sha2::{Digest, Sha256};
use std::path::Path;

fn imported(workers: usize) -> FactSnapshot {
    let fixture = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../fixtures/source-forms");
    import_capture(
        &fixture.join("documents.jsonl"),
        Some(&fixture.join("syntax.jsonl")),
        &ExtractOptions {
            workers,
            ..Default::default()
        },
    )
    .unwrap()
}

fn operations<'a>(facts: &'a FactSnapshot, name: &str) -> &'a [OperationRecord] {
    let body = facts
        .bodies
        .iter()
        .find(|body| facts.symbol_name(body.symbol) == name)
        .unwrap();
    &facts.operations[body.operations.range()]
}

fn calls<'a>(
    facts: &'a FactSnapshot,
    ops: &'a [OperationRecord],
    name: &'a str,
) -> impl Iterator<Item = &'a OperationRecord> + 'a {
    ops.iter().filter(move |op| {
        matches!(op.opcode, Opcode::Call | Opcode::VirtualCall)
            && facts.symbol_name(op.target) == name
    })
}

#[test]
fn frozen_compiler_receipt_and_independent_jvm_witness_match_the_inputs() {
    let fixture = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../fixtures/source-forms");
    let manifest: serde_json::Value =
        serde_json::from_slice(&std::fs::read(fixture.join("manifest.json")).unwrap()).unwrap();
    assert_eq!(manifest["compiler"], "Scala 2.13.18");
    assert_eq!(manifest["plugin"], "SemanticDB 4.15.2");
    assert_eq!(manifest["synthetics"], true);
    assert_eq!(
        manifest["jvm_witness"],
        "source-forms:typed=7:applied=7:placeholder=1:eta=2:named=12:yield=7:receiver=3:bare=4:bare-receiver=5:nullary=7:calls=2255\n"
    );
    for file in manifest["files"].as_array().unwrap() {
        let path = fixture.join(file["path"].as_str().unwrap());
        let hash = ContentHash(Sha256::digest(std::fs::read(path).unwrap()).into());
        assert_eq!(file["sha256"].as_str().unwrap(), hash.to_string());
    }
    // Historical compiler evidence binds the exporter that actually produced
    // it, independently of additive changes to today's live syntax producer.
    let historical = format!(
        "tooling/ScalaSpans-{}.scala",
        manifest["exporter_sha256"].as_str().unwrap()
    );
    let exporter = fixture.join(
        manifest["exporter_snapshot"]
            .as_str()
            .unwrap_or(&historical),
    );
    assert_eq!(
        manifest["exporter_sha256"].as_str().unwrap(),
        ContentHash(Sha256::digest(std::fs::read(exporter).unwrap()).into()).to_string()
    );
}

#[test]
fn compiler_nullary_type_application_calls_once_and_nested_type_arguments_do_not_repeat_calls() {
    for workers in [1, 4] {
        let facts = imported(workers);
        let typed = operations(&facts, "sourceforms/Forms.typed().");
        assert_eq!(
            calls(&facts, typed, "sourceforms/Forms.generic().").count(),
            1
        );
        assert!(!typed.iter().any(|op| op.opcode == Opcode::Unknown));
        let applied = operations(&facts, "sourceforms/Forms.applied().");
        assert_eq!(
            calls(&facts, applied, "sourceforms/Forms.identity().").count(),
            1
        );
        assert_eq!(
            calls(&facts, applied, "sourceforms/Forms.effect().").count(),
            1
        );
        assert!(!applied.iter().any(|op| op.opcode == Opcode::Unknown));
    }
}

#[test]
fn compiler_placeholder_slot_binds_without_an_invented_symbol_occurrence() {
    let facts = imported(2);
    let source = facts.text(facts.files[0].source);
    let body = facts
        .bodies
        .iter()
        .find(|body| {
            facts.symbol_name(body.symbol).starts_with("@closure:")
                && &source[body.span.start as usize..body.span.end as usize] == "identity[Int](_)"
        })
        .unwrap();
    let ops = &facts.operations[body.operations.range()];
    let parameter = ops
        .iter()
        .find(|op| op.opcode == Opcode::Parameter && op.target.is_none())
        .unwrap();
    assert_eq!(
        &source[parameter.span.start as usize..parameter.span.end as usize],
        "_"
    );
    assert!(
        !facts
            .occurrences
            .iter()
            .any(|occurrence| occurrence.span == parameter.span)
    );
    let call = calls(&facts, ops, "sourceforms/Forms.identity().")
        .next()
        .unwrap();
    assert_eq!(&facts.operands[call.arguments.range()], &[parameter.dest]);
    assert!(!ops.iter().any(|op| op.opcode == Opcode::Unknown));
    let initializer = operations(&facts, "sourceforms/Forms.placeholder.");
    assert!(
        initializer
            .iter()
            .any(|op| op.opcode == Opcode::BindCallback)
    );
    assert_eq!(
        calls(&facts, initializer, "sourceforms/Forms.identity().").count(),
        0
    );
}

#[test]
fn compiler_expected_function_type_proves_a_deferred_eta_wrapper() {
    let facts = imported(2);
    let eta = operations(&facts, "sourceforms/Forms.eta.");
    assert_eq!(
        calls(&facts, eta, "sourceforms/Forms.identity().").count(),
        0
    );
    let bind = eta
        .iter()
        .find(|op| op.opcode == Opcode::BindCallback)
        .unwrap();
    let wrapper = operations(&facts, facts.symbol_name(bind.target));
    let parameter = wrapper
        .iter()
        .find(|op| op.opcode == Opcode::Parameter)
        .unwrap();
    let call = calls(&facts, wrapper, "sourceforms/Forms.identity().")
        .next()
        .unwrap();
    assert_eq!(&facts.operands[call.arguments.range()], &[parameter.dest]);
    assert!(
        !eta.iter()
            .chain(wrapper)
            .any(|op| op.opcode == Opcode::Unknown)
    );
    let receiver_factory = operations(&facts, "sourceforms/Forms.receiverEta().");
    let receiver = calls(&facts, receiver_factory, "sourceforms/Forms.receiver().")
        .next()
        .unwrap();
    let bind = receiver_factory
        .iter()
        .find(|op| op.opcode == Opcode::BindCallback)
        .unwrap();
    assert_eq!(bind.a, receiver.dest);
    assert_eq!(
        calls(&facts, receiver_factory, "sourceforms/Forms.identity().").count(),
        0
    );
    let curried = operations(&facts, "sourceforms/Forms.curriedEta.");
    assert!(curried.iter().any(|op| op.opcode == Opcode::Unknown));
    assert_eq!(
        calls(&facts, curried, "sourceforms/Forms.curried().").count(),
        0
    );
}

#[test]
fn bare_method_eta_defers_the_body_and_captures_receiver_effects_once() {
    for workers in [1, 4] {
        let facts = imported(workers);
        for owner in [
            "sourceforms/Forms.bareEta.",
            "sourceforms/Forms.bareReceiverEta().",
        ] {
            let outer = operations(&facts, owner);
            assert_eq!(calls(&facts, outer, "sourceforms/Forms.bare().").count(), 0);
            let bind = outer
                .iter()
                .find(|op| op.opcode == Opcode::BindCallback)
                .unwrap();
            let wrapper = operations(&facts, facts.symbol_name(bind.target));
            let parameter = wrapper
                .iter()
                .find(|op| op.opcode == Opcode::Parameter)
                .unwrap();
            let call = calls(&facts, wrapper, "sourceforms/Forms.bare().")
                .next()
                .unwrap();
            assert_eq!(&facts.operands[call.arguments.range()], &[parameter.dest]);
            assert!(
                !outer
                    .iter()
                    .chain(wrapper)
                    .any(|op| op.opcode == Opcode::Unknown)
            );
            if owner == "sourceforms/Forms.bareReceiverEta()." {
                let receiver =
                    calls(&facts, outer, "sourceforms/Forms.receiver().").collect::<Vec<_>>();
                assert_eq!(receiver.len(), 1);
                assert_eq!(bind.a, receiver[0].dest);
            }
        }
        let nullary = operations(&facts, "sourceforms/Forms.nullaryBare().");
        assert_eq!(
            calls(&facts, nullary, "sourceforms/Forms.effect().").count(),
            1
        );
        assert!(
            !nullary
                .iter()
                .any(|op| matches!(op.opcode, Opcode::BindCallback | Opcode::Unknown))
        );
    }
}

#[test]
fn incomplete_bare_eta_proof_retains_unknown_and_receiver_effects_without_invoking_method() {
    let fixture = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../fixtures/source-forms");
    for missing in ["expected_function", "parameter_mode"] {
        let temporary = tempfile::tempdir().unwrap();
        let mut row: serde_json::Value =
            serde_json::from_slice(&std::fs::read(fixture.join("documents.jsonl")).unwrap())
                .unwrap();
        for symbol in row["document"]["symbols"].as_array_mut().unwrap() {
            if missing == "expected_function"
                && matches!(
                    symbol["symbol"].as_str(),
                    Some("sourceforms/Forms.bareEta." | "sourceforms/Forms.bareReceiverEta().")
                )
            {
                symbol["signature"]["method_signature"]["return_type"] =
                    serde_json::json!({"type_ref":{"symbol":"scala/Int#"}});
            } else if missing == "parameter_mode"
                && symbol["symbol"] == "sourceforms/Forms.bare().(value)"
            {
                symbol.as_object_mut().unwrap().remove("signature");
            }
        }
        let path = temporary.path().join("documents.jsonl");
        std::fs::write(&path, serde_json::to_vec(&row).unwrap()).unwrap();
        let facts = import_capture(
            &path,
            Some(&fixture.join("syntax.jsonl")),
            &ExtractOptions::default(),
        )
        .unwrap();
        for owner in [
            "sourceforms/Forms.bareEta.",
            "sourceforms/Forms.bareReceiverEta().",
        ] {
            let outer = operations(&facts, owner);
            assert!(
                outer.iter().any(|op| op.opcode == Opcode::Unknown),
                "{missing}:{owner}"
            );
            assert_eq!(
                calls(&facts, outer, "sourceforms/Forms.bare().").count(),
                0,
                "{missing}:{owner}"
            );
            if owner == "sourceforms/Forms.bareReceiverEta()." {
                assert_eq!(
                    calls(&facts, outer, "sourceforms/Forms.receiver().").count(),
                    1
                );
            }
        }
    }
}

#[test]
fn compiler_generator_function_owns_its_source_calls_without_deferring_the_generator() {
    let facts = imported(2);
    let outer = operations(&facts, "sourceforms/Forms.yielding().");
    assert_eq!(
        calls(&facts, outer, "sourceforms/Forms.identity().").count(),
        0
    );
    assert_eq!(
        calls(&facts, outer, "sourceforms/Forms.effect().").count(),
        1
    );
    assert!(outer.iter().any(|op| op.opcode == Opcode::BindCallback));
    let function = facts
        .bodies
        .iter()
        .find(|body| {
            facts
                .symbol_name(body.symbol)
                .starts_with("@synthetic-closure:")
                && facts.symbol_name(facts.symbols[body.symbol.index()].owner)
                    == "sourceforms/Forms.yielding()."
        })
        .unwrap();
    let callback = &facts.operations[function.operations.range()];
    assert_eq!(
        calls(&facts, callback, "sourceforms/Forms.identity().").count(),
        1
    );
    assert_eq!(
        calls(&facts, callback, "sourceforms/Forms.effect().").count(),
        0
    );
}

#[test]
fn compiler_named_arguments_keep_written_evaluation_order_and_formal_binding_order() {
    let facts = imported(2);
    let ops = operations(&facts, "sourceforms/Forms.namedCall().");
    let second = calls(&facts, ops, "sourceforms/Forms.second().")
        .next()
        .unwrap();
    let first = calls(&facts, ops, "sourceforms/Forms.first().")
        .next()
        .unwrap();
    assert!(second.span.start < first.span.start);
    assert!(
        ops.iter().position(|op| std::ptr::eq(op, second)).unwrap()
            < ops.iter().position(|op| std::ptr::eq(op, first)).unwrap()
    );
    let call = calls(&facts, ops, "sourceforms/Forms.named().")
        .next()
        .unwrap();
    assert_eq!(
        &facts.operands[call.arguments.range()],
        &[first.dest, second.dest]
    );
    assert!(!ops.iter().any(|op| op.opcode == Opcode::Unknown));
}

#[test]
fn incomplete_complex_forms_keep_known_child_effects_and_explicit_uncertainty() {
    let facts = imported(2);
    for name in [
        "sourceforms/Forms.interpolate().",
        "sourceforms/Forms.yielding().",
    ] {
        let ops = operations(&facts, name);
        assert_eq!(
            calls(&facts, ops, "sourceforms/Forms.effect().").count(),
            1,
            "{name}"
        );
        assert!(ops.iter().any(|op| op.opcode == Opcode::Unknown));
    }
}
